"""
Patch 10 (30 October 2026): the investor site on the 30 October narrative rules.
No per-vehicle dollar figures, no forecast or plan-case table, no growth-capital amount, no Texas or Maritimes,
audited FY2025 and FY2024 only (FY2023 column dropped), the 30 October document set on the Presentations page
with real PDFs under assets/documents, a visible SEDAR+ link on the home, financials and presentations pages,
Matthew's bio line, Hasneen 'leads technology and the demand engine'.
Each replacement must match exactly once; the script stops on the first miss so nothing is half-applied.
"""
import os, io, sys

HERE = os.path.dirname(os.path.abspath(__file__))

def apply(fn, pairs):
    p = os.path.join(HERE, fn)
    s = io.open(p, encoding="utf-8").read()
    for old, new in pairs:
        n = s.count(old)
        if n != 1:
            sys.exit("%s: expected 1 match, found %d for:\n%s" % (fn, n, old[:160]))
        s = s.replace(old, new)
    io.open(p, "w", encoding="utf-8", newline="\n").write(s)
    print(fn, "patched:", len(pairs))

